// Helper to generate personalized Hinglish WhatsApp proposal message with itemized service breakdown
export function generatePackageWhatsAppMessage(
  pkg, 
  lead, 
  senderName = 'Dhruv Rana', 
  senderPhone = '+91 98700 98180',
  chosenPlanKey = 'all'
) {
  const companyName = lead?.name || 'Your Company';
  const dmName = lead?.dm || 'Director';
  const city = lead?.city || 'Gujarat';
  const category = lead?.category || 'Manufacturing';

  const plans = pkg.paymentPlans || {};
  const breakdown = pkg.itemizedBreakdown || [];

  // Itemized breakdown text
  const itemizedText = breakdown.map((item) => {
    const monthlyPart = item.monthly > 0 ? ` + ₹${item.monthly.toLocaleString('en-IN')}/mo` : '';
    return `  ▪️ *${item.service}*: Setup ₹${item.setup.toLocaleString('en-IN')}${monthlyPart}\n    (${item.desc})`;
  }).join('\n');

  let paymentSection = '';
  if (chosenPlanKey === 'monthly' && plans.monthly) {
    paymentSection = `💳 *Payment Option Selected: Monthly Flexi*
• One-Time Setup: *₹${plans.monthly.setupFee.toLocaleString('en-IN')}* (50% Advance + 50% on Go-Live)
• Monthly Retainer: *₹${plans.monthly.retainer.toLocaleString('en-IN')}/mo*
• Billing Cycle: Billed monthly on 1st`;
  } else if (chosenPlanKey === 'quarterly' && plans.quarterly) {
    paymentSection = `💳 *Payment Option Selected: Quarterly Growth (Save 10%)*
• One-Time Setup: *₹${plans.quarterly.setupFee.toLocaleString('en-IN')}*
• Monthly Retainer: *₹${plans.quarterly.retainer.toLocaleString('en-IN')}/mo* (Discounted)
• 3-Month Total: *₹${plans.quarterly.quarterlyTotal.toLocaleString('en-IN')}* (${plans.quarterly.savings})
• Billing Cycle: Every 3 months`;
  } else if (chosenPlanKey === 'annual' && plans.annual) {
    paymentSection = `💳 *Payment Option Selected: Annual Domination (Save 20% + Setup Discount)*
• One-Time Setup: *₹${plans.annual.setupFee.toLocaleString('en-IN')}* (Special discount)
• Monthly Retainer: *₹${plans.annual.retainer.toLocaleString('en-IN')}/mo*
• Full Year Total: *₹${plans.annual.annualTotal.toLocaleString('en-IN')}* (${plans.annual.savings})
• Billing Cycle: Annual (12 months complete management)`;
  } else {
    // Show total package pricing & options
    paymentSection = `💰 *Complete Package Commercials:*
• Total Setup Investment: *₹${pkg.setupFee.toLocaleString('en-IN')}*
• Total Monthly Retainer: *₹${pkg.monthlyFee.toLocaleString('en-IN')}/month*
🎁 *Bundle Benefit:* ${pkg.savingsText}

*Flexible Payment Choices:*
1️⃣ Monthly: ₹${pkg.setupFee.toLocaleString('en-IN')} + ₹${pkg.monthlyFee.toLocaleString('en-IN')}/mo
2️⃣ Quarterly (10% OFF): Retainer @ ₹${plans.quarterly?.retainer.toLocaleString('en-IN')}/mo
3️⃣ Annual (20% OFF): Retainer @ ₹${plans.annual?.retainer.toLocaleString('en-IN')}/mo`;
  }

  return `Namaste ${dmName} ji,

I am ${senderName} from Gujarat B2B Web & Digital Solutions (${senderPhone}).
Following up regarding 360° digital lead acceleration for *${companyName}* in ${city}.

Here is the *Service-Wise Itemized Rate Card & Proposal* for *${pkg.name}* (${pkg.hindiName}):

📊 *Itemized Deliverables & Pricing Breakdown:*
${itemizedText}

--------------------------------------
${paymentSection}
--------------------------------------

🎯 *Payment Milestones:*
• Milestone 1: 50% advance upon kickoff & ad account audit
• Milestone 2: 50% setup balance upon website go-live & ad launch
• Platform Ad Spend: Meta & Google ad budgets are paid directly from your business card with 100% GST input tax credit (ITC).

📄 *Official Quotation PDF & Service Brochure has also been generated for ${companyName}.*

Can we schedule a quick 15-minute meeting or call on Wednesday/Thursday to walk you through the mockup?

Best Regards,
${senderName}
B2B Digital Growth Architect
Phone: ${senderPhone}`;
}
